# Writes src/generated.jl from the plotly.js schema in the `plotly_artifacts` artifact (see Artifacts.toml).
# Run after updating the artifact:  julia deps/generate.jl
using Pkg
Pkg.activate(@__DIR__)
Pkg.instantiate()

using JSON

root = joinpath(@__DIR__, "..")
dir = Pkg.Artifacts.ensure_artifact_installed("plotly_artifacts", joinpath(root, "Artifacts.toml"))
version = strip(read(joinpath(dir, "version.txt"), String))
traces = JSON.parsefile(joinpath(dir, "plot-schema.json"))["traces"]

# `items` separated by ", " on lines of at most `width` characters, each starting with `indent`
function wrap(items, indent; width=120)
    lines = [indent * first(items)]
    for item in items[2:end]
        if length(lines[end]) + length(", " * item * ",") > width  # (room for the comma ending a full line)
            lines[end] *= ","
            push!(lines, indent * item)
        else
            lines[end] *= ", " * item
        end
    end
    join(lines, "\n")
end

open(joinpath(root, "src", "generated.jl"), "w") do io
    println(io, "# Generated by deps/generate.jl from plotly.js $version's plot-schema.json.  Don't edit by hand.")
    println(io)
    println(io, "# Trace type => its attributes (top-level only)")
    println(io, "const schema = Dict{Symbol, Set{Symbol}}(")
    foreach(sort!(collect(keys(traces)))) do t
        attrs = map(a -> repr(Symbol(a)), sort!(collect(keys(traces[t]["attributes"]))))
        println(io, "    ", repr(Symbol(t)), " => Set([")
        println(io, wrap(attrs, "        "))
        println(io, "    ]),")
    end
    println(io, ")")
end
